import { ValidatedAnalysis } from "./schema";
import { getConcernCategoryLabel, getMissingInfoTopicLabel } from "./labels";
import { selectSelfChecks } from "@/data/self-checks";
import { selectResources } from "./resources";
import { sortConcernsByPriority } from "./priorities";

/**
 * Builds a clean, plain-text exportable summary from a ValidatedAnalysis object.
 *
 * Requirements:
 * - Must contain the exact title and standard disclaimer:
 *   "Generated by OfferCheck from pasted text. Not a safety assessment."
 * - Must NOT contain any model names, latency metrics, or attempt logs.
 * - Accurately lists potential concerns, missing info, verification questions,
 *   self-check actions, official resources, and review limits.
 * - Handles empty or zero-concern analyses with neutral, cautious phrasing.
 */
export function buildReviewSummary(
  analysis: ValidatedAnalysis,
  sourceText: string = "",
  extraContext?: { sourceNote?: string; conversationText?: string }
): string {
  const lines: string[] = [];

  // Title and Core Notice
  lines.push("OfferCheck Review Summary");
  lines.push("Generated by OfferCheck from pasted text. Not a safety assessment.");
  lines.push("");

  // Overall Note (if present)
  if (analysis.overallNote) {
    lines.push(`Note: ${analysis.overallNote}`);
    lines.push("");
  }

  // Source note & described conversation (if present)
  if (extraContext?.sourceNote) {
    lines.push(`Source note: ${extraContext.sourceNote}`);
  }
  if (extraContext?.conversationText) {
    lines.push(`Described conversation: ${extraContext.conversationText}`);
  }
  if (extraContext?.sourceNote || extraContext?.conversationText) {
    lines.push("");
  }

  // Notice for dropped unverified quotes (if any)
  if (analysis.droppedCount > 0) {
    lines.push(
      `Notice: ${analysis.droppedCount} item(s) were removed because their supporting quotes could not be matched to your text.`
    );
    lines.push("");
  }

  // Entities (if present)
  if (analysis.entities && (analysis.entities.companyName || analysis.entities.roleTitle)) {
    if (analysis.entities.companyName) {
      lines.push(`Company name: ${analysis.entities.companyName}`);
    }
    if (analysis.entities.roleTitle) {
      lines.push(`Role title: ${analysis.entities.roleTitle}`);
    }
    lines.push("");
  }

  const sortedConcerns = sortConcernsByPriority(analysis.concerns);
  const categories = sortedConcerns.map((c) => c.category);

  // Section A: Potential Concerns
  lines.push("--- POTENTIAL CONCERNS ---");
  if (sortedConcerns.length === 0) {
    lines.push(
      "No specific concerns were identified in the text provided. This is not a safety assessment."
    );
  } else {
    for (const [idx, c] of sortedConcerns.entries()) {
      const categoryLabel = getConcernCategoryLabel(c.category);
      lines.push(`${idx + 1}. [${categoryLabel}]`);
      lines.push(`   What the text says: ${c.observation}`);
      lines.push(`   Why it may matter: ${c.interpretation}`);
      lines.push(`   From your text: "${c.quote}"`);
    }
  }
  lines.push("");

  // Section B: Missing or Unclear Information
  lines.push("--- MISSING OR UNCLEAR INFORMATION ---");
  lines.push(
    "Note: Terms not mentioned in the provided text does not prove they do not exist."
  );
  if (analysis.missingInfo.length === 0) {
    lines.push("No missing terms noted.");
  } else {
    for (const [idx, m] of analysis.missingInfo.entries()) {
      const topicLabel = getMissingInfoTopicLabel(m.topic);
      lines.push(`${idx + 1}. [${topicLabel}]`);
      lines.push(`   ${m.note}`);
    }
  }
  lines.push("");

  // Section C: Questions to Verify
  lines.push("--- QUESTIONS TO VERIFY ---");
  if (analysis.verificationQuestions.length === 0) {
    lines.push("No verification questions drafted.");
  } else {
    for (const [idx, q] of analysis.verificationQuestions.entries()) {
      lines.push(`${idx + 1}. ${q.question}`);
    }
  }
  lines.push("");

  // Section: Check These Yourself (Self-checks)
  const selfChecks = selectSelfChecks(categories);
  lines.push("--- CHECK THESE YOURSELF ---");
  lines.push(
    "Independent verification steps you can take yourself:"
  );
  for (const [idx, sc] of selfChecks.entries()) {
    lines.push(`${idx + 1}. ${sc.text}`);
  }
  lines.push("");

  // Section: Official Resources
  const resources = selectResources(categories, sourceText);
  lines.push("--- OFFICIAL RESOURCES ---");
  lines.push(
    "Official verification portals and helplines (OfferCheck does not vouch for any sender):"
  );
  for (const [idx, rItem] of resources.entries()) {
    const r = rItem.resource;
    lines.push(`${idx + 1}. [${r.title}]`);
    if (rItem.matchedTerm) {
      lines.push(`   Shown because your text mentions "${rItem.matchedTerm}".`);
    }
    lines.push(`   ${r.summary}`);
    for (const act of r.actions) {
      lines.push(`   - ${act.label} (${act.type}): ${act.value}`);
    }
  }
  lines.push("");

  // Section D: Limits of this Review
  lines.push("--- LIMITS OF THIS REVIEW ---");
  for (const lim of analysis.limits) {
    lines.push(`- ${lim}`);
  }

  return lines.join("\n");
}
